<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ArrowLeft, Check, Clock3, FileImage, LoaderCircle, MessageSquare, Save, Send, Sparkles, Upload, XCircle } from '@lucide/vue'; import { api, type PostDetail, type Variant } from '../lib/api'; import { useSessionStore } from '../stores/session'
const route=useRoute();const router=useRouter();const session=useSessionStore();const post=ref<PostDetail|null>(null);const busy=ref('');const notice=ref('');const error=ref('');const drafts=ref<Record<string,{copywriting:string;hashtags:string}>>({});const scheduleAt=ref<Record<string,string>>({});const failure=ref<Record<string,boolean>>({});const returnText=ref<Record<string,string>>({});const comment=ref('');const selectedCommentVariant=ref<string|null>(null)
const campaignId=String(route.params.campaignId),postId=String(route.params.postId);const canEdit=computed(()=>['owner','admin','editor'].includes(session.workspace?.role??''));const canReview=computed(()=>['owner','admin','reviewer'].includes(session.workspace?.role??''));const allDraftReady=computed(()=>post.value?.variants.every(v=>drafts.value[v.id]?.copywriting.trim())&&post.value.assets.length)
async function load(){post.value=await api.post(campaignId,postId);for(const v of post.value.variants){drafts.value[v.id]={copywriting:v.copywriting,hashtags:parseTags(v.hashtags).join(' ')};scheduleAt.value[v.id]=toInput(v.scheduledAt??Date.now()+3600000)}}
async function action(key:string,fn:()=>Promise<unknown>,message:string){busy.value=key;error.value='';notice.value='';try{await fn();await load();notice.value=message}catch(e){error.value=e instanceof Error?e.message:'操作失敗'}finally{busy.value=''}}
async function upload(e:Event){const input=e.target as HTMLInputElement;if(!input.files?.length)return;await action('upload',()=>api.uploadAssets(campaignId,postId,input.files!),'素材已加入貼文');input.value=''}
async function generate(){busy.value='generate';error.value='';try{await api.generatePost(campaignId,postId);for(let i=0;i<30;i++){await new Promise(r=>setTimeout(r,500));await load();if(!post.value?.jobs.some(j=>['queued','processing'].includes(j.status))){notice.value='平台文案已產生';return}}error.value='生成時間較長，請稍後重新整理'}catch(e){error.value=e instanceof Error?e.message:'生成失敗'}finally{busy.value=''}}
async function save(v:Variant){const draft=drafts.value[v.id];await action(v.id,()=>api.updateVariant(campaignId,postId,v.id,draft.copywriting,draft.hashtags.split(/[\s,，]+/).map(t=>t.replace(/^#/,'')).filter(Boolean)),'平台內容已儲存')}
async function requestChanges(v:Variant){const value=returnText.value[v.id]?.trim();if(!value){error.value='退回時請填寫修改原因';return}await action(v.id,()=>api.requestChanges(campaignId,postId,v.id,value),'已退回修改')}
async function schedule(v:Variant){const time=new Date(scheduleAt.value[v.id]).getTime();if(!Number.isFinite(time)){error.value='請選擇排程時間';return}await action(v.id,()=>api.schedule(campaignId,postId,v.id,time,failure.value[v.id]??false),'平台版本已排程')}
async function addComment(){if(!comment.value.trim())return;await action('comment',()=>api.addComment(campaignId,postId,comment.value,selectedCommentVariant.value),'留言已新增');comment.value=''}
function parseTags(raw:string){try{return JSON.parse(raw)as string[]}catch{return raw.split(/\s+/).filter(Boolean)}}function toInput(value:number){const d=new Date(value-new Date(value).getTimezoneOffset()*60000);return d.toISOString().slice(0,16)}
onMounted(load)
</script>
<template><div v-if="post" class="page-stack post-editor-page"><button class="back-link" @click="router.push(`/campaigns/${campaignId}`)"><ArrowLeft :size="16"/>返回企劃</button><section class="post-editor-head"><div><div class="title-line"><span class="format-badge">{{post.format}}</span><h2>{{post.title}}</h2></div><p>{{post.brief||'尚未填寫貼文簡介'}}</p></div><div><button v-if="canEdit" class="button secondary" :disabled="!!busy||!post.assets.length" @click="generate"><LoaderCircle v-if="busy==='generate'" class="spin" :size="17"/><Sparkles v-else :size="17"/>AI 生成文案</button><button v-if="canEdit" class="button primary" :disabled="!!busy||!allDraftReady" @click="action('review',()=>api.submitReview(campaignId,postId),'已送出團隊審核')"><Send :size="17"/>送出審核</button></div></section><p v-if="notice" class="notice">{{notice}}</p><p v-if="error" class="form-error banner">{{error}}</p><div class="editor-layout"><div class="editor-main"><section class="panel"><div class="panel-head"><div><p class="eyebrow">MEDIA</p><h3>貼文素材</h3></div><label v-if="canEdit" class="button secondary upload-control"><Upload :size="16"/>上傳素材<input data-testid="asset-input" type="file" multiple :accept="post.format==='short_video'?'video/mp4,video/webm':'image/jpeg,image/png,image/webp'" @change="upload"></label></div><div v-if="post.assets.length" class="media-grid"><div v-for="asset in post.assets" :key="asset.id"><video v-if="asset.mediaType==='video'" controls :src="api.assetUrl(campaignId,postId,asset.id)"/><img v-else :src="api.assetUrl(campaignId,postId,asset.id)" :alt="asset.fileName"><small>{{asset.fileName}}</small></div></div><div v-else class="empty-block"><FileImage/><p>加入素材後即可產生平台文案</p></div></section><section class="panel"><div class="panel-head"><div><p class="eyebrow">PLATFORM VARIANTS</p><h3>平台內容</h3></div><span>{{post.variants.length}} 個版本</span></div><div class="variant-list"><article v-for="variant in post.variants" :key="variant.id" class="variant-card"><header><strong><i class="platform-dot"/>{{variant.platform}}</strong><span class="status-chip" :class="variant.status">{{variant.status}}</span></header><label>文案<textarea v-model="drafts[variant.id].copywriting" rows="6" :readonly="!canEdit||!['draft','changes_requested'].includes(variant.status)" placeholder="輸入或使用 AI 產生平台文案"></textarea></label><label>Hashtags<input v-model="drafts[variant.id].hashtags" :readonly="!canEdit||!['draft','changes_requested'].includes(variant.status)" placeholder="品牌內容 社群企劃"></label><div v-if="canEdit&&['draft','changes_requested'].includes(variant.status)" class="variant-actions"><button class="button secondary" :disabled="busy===variant.id" @click="save(variant)"><Save :size="15"/>儲存版本</button></div><div v-if="canReview&&variant.status==='in_review'" class="review-actions"><button class="button approve" :disabled="!!busy" @click="action(variant.id,()=>api.approve(campaignId,postId,variant.id),'平台版本已核准')"><Check :size="15"/>核准</button><label><input v-model="returnText[variant.id]" placeholder="填寫退回原因"><button class="button danger" :disabled="!!busy" @click="requestChanges(variant)"><XCircle :size="15"/>退回</button></label></div><div v-if="canEdit&&['approved','scheduled','failed'].includes(variant.status)" class="schedule-box"><label>發布時間<input v-model="scheduleAt[variant.id]" type="datetime-local"></label><label class="check-control"><input v-model="failure[variant.id]" type="checkbox">模擬首次發布失敗</label><button class="button secondary" :disabled="!!busy" @click="schedule(variant)"><Clock3 :size="15"/>{{variant.status==='scheduled'?'更新排程':'加入排程'}}</button></div></article></div></section></div><aside class="comment-panel"><div class="panel-head"><div><p class="eyebrow">REVIEW THREAD</p><h3>協作留言</h3></div><MessageSquare :size="19"/></div><div class="comment-list"><article v-for="item in post.comments" :key="item.id" :class="{resolved:item.resolvedAt}"><div><strong>{{item.authorName}}</strong><span>{{new Date(item.createdAt).toLocaleString('zh-TW')}}</span></div><small v-if="item.variantId">平台版本留言</small><p>{{item.body}}</p><button v-if="!item.resolvedAt&&canEdit" @click="action('resolve',()=>api.resolveComment(campaignId,postId,item.id),'留言已解決')">標記已解決</button></article><p v-if="!post.comments.length" class="muted">尚無留言</p></div><form v-if="session.workspace?.role!=='viewer'" @submit.prevent="addComment"><select v-model="selectedCommentVariant"><option :value="null">整篇貼文</option><option v-for="v in post.variants" :key="v.id" :value="v.id">{{v.platform}}</option></select><textarea v-model="comment" rows="3" placeholder="留下具體的修改建議…"></textarea><button class="button primary" :disabled="busy==='comment'">新增留言</button></form></aside></div></div></template>
